'use strict';

const util = require('util');
const is = require('is-type-of');
const utility = require('utility');
const version = require('../package.json').version;

class PollingRequest {
  constructor(options = {}) {
    this.requestTimeLimitMS = 15000;
    this.from = 'nodejs-client';
    this.clientVersion = version;
    this.allowPolling = is.boolean(options.allowPolling) ? options.allowPolling : true;
    this.nameListChecksum = null;
    this.datacenter = options.datacenter || null;
    this.vipDomainName2ChecksumMap = options.vipDomainName2ChecksumMap || null;
    this.startTime = null;
    this.acceptTime = null;
    this.extensionParams = options.extensionParams || null;
    this.buildSecurityContext(options);
  }

  buildSecurityContext(options) {
    if (!options || !options.accessKey || !options.accessSecret) {
      return;
    }
    this.extensionParams = this.extensionParams || {};
    const { accessKey, accessSecret, instanceId } = options;
    const cacheTime = 5 * 60 * 1000;
    const timestamp = String(Math.round(Date.now() / cacheTime) * cacheTime);
    const content = instanceId + timestamp;
    this.extensionParams.accessKey = accessKey;
    this.extensionParams.accessInstanceId = instanceId;
    this.extensionParams.accessAlgorithm = 'HmacSHA256';
    this.extensionParams.accessContent = content;
    this.extensionParams.accessSignature = utility.hmac('sha256', accessSecret, content, 'base64');
    this.extensionParams.accessTimestamp = timestamp;
  }

  toString() {
    return util.format('PollingRequest [requestTimeLimitMS=%s, from=%s, clientVersion=%s, allowPolling=%s, nameListChecksum=%s, datacenter=%s, vipDomainName2ChecksumMap.size=%s, startTime=%s, acceptTime=%s, extensionParams=%j]',
      this.requestTimeLimitMS, this.from, this.clientVersion, this.allowPolling,
      this.nameListChecksum, this.datacenter, (this.vipDomainName2ChecksumMap ?
        Object.keys(this.vipDomainName2ChecksumMap) : null),
      this.startTime, this.acceptTime, this.extensionParams);
  }
}

module.exports = PollingRequest;
